"""Write docs/reference/cli.md, the command-line reference, from the Typer app (design 23 C5).

Run it with ``uv run poe docs-cli``. Only ``typer.main.get_command`` and the public attributes of the
commands it returns are used, so the text depends on the help strings and nothing else: not on the terminal,
the colour setting, the machine or the settings.
"""

from __future__ import annotations

import inspect
import textwrap
from pathlib import Path
from typing import Any

import typer

from tlaup.cli import app

WIDTH = 100
HEADER = (
    "<!-- Generated by scripts/gen_cli_reference.py; update it with `uv run poe docs-cli`\n"
    "     (or `pytest --update-expected`) and do not edit it by hand. -->"
)
REFERENCE = Path(__file__).resolve().parent.parent / "docs" / "reference" / "cli.md"


def _paragraphs(text: str | None) -> list[str]:
    """The text as stored, split at blank lines; plain paragraphs are wrapped at WIDTH, indented ones kept."""
    if not text:
        return []
    out: list[str] = []
    for block in inspect.cleandoc(text).replace("\b", "").split("\n\n"):
        lines = [line.rstrip() for line in block.split("\n")]
        if any(line.startswith((" ", "\t")) for line in lines):
            out.append("\n".join(lines))
        else:
            out.append(textwrap.fill(" ".join(lines), WIDTH))
    return out


def _usage(command: Any, parent: Any, name: str) -> str:
    ctx = command.make_context(
        name, [], parent=parent, resilient_parsing=True, terminal_width=WIDTH, max_content_width=WIDTH
    )
    usage = " ".join(command.get_usage(ctx).split())
    return textwrap.fill(usage.removeprefix("Usage: "), WIDTH, subsequent_indent="    ")


def _param(param: Any) -> str:
    if param.param_type_name == "option":
        names = ", ".join(param.opts + param.secondary_opts)
        label = names if param.is_flag else f"{names} {param.metavar or str(param.name).upper()}"
    else:
        label = param.metavar or str(param.name).upper()
        if param.nargs != 1 and not label.endswith("..."):
            label += "..."
    text = getattr(param, "help", None) or ""
    text = " ".join(text.split())
    if param.required:
        text = f"{text} (required)".strip()
    return textwrap.fill(
        f"- `{label}`" + (f": {text}" if text else ""), WIDTH, subsequent_indent="  ", break_long_words=False
    )


def _command(command: Any, path: list[str], parent: Any, depth: int) -> list[str]:
    ctx = command.make_context(
        path[-1], [], parent=parent, resilient_parsing=True, terminal_width=WIDTH, max_content_width=WIDTH
    )
    out = [f"{'#' * min(depth, 6)} `{' '.join(path)}`", "", "```text", _usage(command, parent, path[-1]), "```", ""]
    for paragraph in _paragraphs(command.help):
        out += [paragraph, ""]
    params = [p for p in command.get_params(ctx) if not (p.param_type_name == "option" and getattr(p, "hidden", False))]
    arguments = [p for p in params if p.param_type_name == "argument"]
    options = [p for p in params if p.param_type_name != "argument"]
    for title, group in (("Arguments", arguments), ("Options", options)):
        if group:
            out += [f"{title}:", ""] + [_param(p) for p in group] + [""]
    if command.epilog:
        out += ["```text", "\n\n".join(_paragraphs(command.epilog)), "```", ""]
    if hasattr(command, "commands"):
        panels: dict[str, list[str]] = {}
        for name in command.list_commands(ctx):
            sub = command.commands[name]
            panels.setdefault(getattr(sub, "rich_help_panel", None) or "Commands", []).append(name)
        for panel, names in panels.items():
            out += [f"{panel}:", ""]
            for name in names:
                sub = command.commands[name]
                first = " ".join((sub.short_help or (_paragraphs(sub.help) or [""])[0]).split())
                out.append(textwrap.fill(f"- `{name}`: {first}", WIDTH, subsequent_indent="  "))
            out.append("")
        for panel_names in panels.values():
            for name in panel_names:
                out += _command(command.commands[name], [*path, name], ctx, depth + 1)
    return out


def render_reference(app: typer.Typer) -> str:
    """The reference as Markdown: every command and group, depth first, in the order the help lists them."""
    root: Any = typer.main.get_command(app)
    lines = [HEADER, "", "# tlaup command-line reference", ""]
    lines += _command(root, ["tlaup"], None, 2)
    return "\n".join(line.rstrip() for line in lines).rstrip("\n") + "\n"


def main() -> None:
    REFERENCE.parent.mkdir(parents=True, exist_ok=True)
    REFERENCE.write_text(render_reference(app), encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
